import json

with open('/app/output/crypto_data.json') as f:
    data = json.load(f)

js = """
(function() {
  const cryptoData = """ + json.dumps(data) + """;

  const tableBody = document.getElementById('tableBody');
  const pagination = document.getElementById('pagination');
  const promoTrack = document.getElementById('promoTrack');
  const readMoreBtn = document.getElementById('readMoreBtn');
  const marketExtra = document.getElementById('marketExtra');
  const readMoreIcon = document.getElementById('readMoreIcon');
  const btnFilters = document.getElementById('btnFilters');
  const filtersPanel = document.getElementById('filtersPanel');
  const btnColumns = document.getElementById('btnColumns');
  const columnsPanel = document.getElementById('columnsPanel');
  const sortMcap = document.getElementById('sortMcap');
  const sortVol = document.getElementById('sortVol');

  let currentPage = 1;
  let currentSort = 'mcap';
  let sortDir = 'desc';
  let currentCategory = 'top';
  let currentNetwork = 'all';
  let visibleCols = new Set(['rank','name','price','1h','24h','7d','mcap','vol','supply','sparkline']);

  function renderTable() {
    let rows = [...cryptoData];
    if (currentCategory !== 'top') {
      rows = rows.filter((_, i) => {
        if (currentCategory === 'trending') return i < 20;
        if (currentCategory === 'watchlist') return [0,1,5,10,15,20,25,30,35,40].includes(i);
        if (currentCategory === 'prediction') return [3,8,12,18,22,28,33,38,42,48].includes(i);
        if (currentCategory === 'visited') return i < 50;
        if (currentCategory === 'new') return i >= 80;
        return true;
      });
    }
    if (currentNetwork !== 'all') {
      const netMap = { bsc: [4,24,40], solana: [5,35,45,55,65,75,85,95], base: [1,11,21,31,41,51,61,71,81,91], ethereum: [1,0,2,3,6,7,8,9,10,12,13,14,15,16,17,18,19,20] };
      const allowed = netMap[currentNetwork] || [];
      rows = rows.filter(r => allowed.includes(r.rank - 1));
    }
    rows.sort((a, b) => {
      let av, bv;
      if (currentSort === 'rank') { av = a.rank; bv = b.rank; }
      else if (currentSort === 'name') { av = a.name; bv = b.name; }
      else if (currentSort === 'price') { av = parseFloat(a.price.replace(/[^0-9.]/g,'')); bv = parseFloat(b.price.replace(/[^0-9.]/g,'')); }
      else if (currentSort === 'h1') { av = parseFloat(a.h1.replace('%','')); bv = parseFloat(b.h1.replace('%','')); }
      else if (currentSort === 'h24') { av = parseFloat(a.h24.replace('%','')); bv = parseFloat(b.h24.replace('%','')); }
      else if (currentSort === 'd7') { av = parseFloat(a.d7.replace('%','')); bv = parseFloat(b.d7.replace('%','')); }
      else if (currentSort === 'mcap') { av = a.mcap; bv = b.mcap; }
      else if (currentSort === 'vol') { av = a.vol; bv = b.vol; }
      else if (currentSort === 'supply') { av = a.supply; bv = b.supply; }
      else { av = a.rank; bv = b.rank; }
      if (typeof av === 'string' && av.startsWith('$')) {
        const parseVal = s => {
          const n = parseFloat(s.replace(/[^0-9.]/g,''));
          if (s.includes('T')) return n * 1e12;
          if (s.includes('B')) return n * 1e9;
          if (s.includes('M')) return n * 1e6;
          return n;
        };
        av = parseVal(av); bv = parseVal(bv);
      }
      if (av < bv) return sortDir === 'asc' ? -1 : 1;
      if (av > bv) return sortDir === 'asc' ? 1 : -1;
      return 0;
    });

    const start = (currentPage - 1) * 100;
    const pageRows = rows.slice(start, start + 100);

    tableBody.innerHTML = pageRows.map(r => `
      <tr>
        ${visibleCols.has('rank') ? `<td class="col-rank"><span class="rank-cell">${r.rank}</span></td>` : ''}
        ${visibleCols.has('name') ? `<td class="col-name">
          <div class="coin-cell">
            <div class="coin-icon" style="background:${r.color}">${r.symbol[0]}</div>
            <div class="coin-info">
              <span class="coin-name">${r.name}</span>
              <span class="coin-symbol">${r.symbol}</span>
            </div>
          </div>
        </td>` : ''}
        ${visibleCols.has('price') ? `<td class="col-price"><span class="num">${r.price}</span></td>` : ''}
        ${visibleCols.has('1h') ? `<td class="col-1h"><span class="pct ${r.h1_cls}">${r.h1}</span></td>` : ''}
        ${visibleCols.has('24h') ? `<td class="col-24h"><span class="pct ${r.h24_cls}">${r.h24}</span></td>` : ''}
        ${visibleCols.has('7d') ? `<td class="col-7d"><span class="pct ${r.d7_cls}">${r.d7}</span></td>` : ''}
        ${visibleCols.has('mcap') ? `<td class="col-mcap"><span class="num">${r.mcap}</span></td>` : ''}
        ${visibleCols.has('vol') ? `<td class="col-vol"><span class="num">${r.vol}</span></td>` : ''}
        ${visibleCols.has('supply') ? `<td class="col-supply"><span class="num">${r.supply}</span></td>` : ''}
        ${visibleCols.has('sparkline') ? `<td class="col-sparkline">${r.sparkline}</td>` : ''}
      </tr>
    `).join('');

    const total = rows.length;
    const startIdx = total ? start + 1 : 0;
    const endIdx = Math.min(start + 100, total);
    pagination.querySelector('.page-info').textContent = `Showing ${startIdx}–${endIdx} of ${total.toLocaleString()} assets`;
  }

  // Promo carousel
  let slideIdx = 0;
  const slideCount = 3;
  function updateSlide() {
    promoTrack.style.transform = `translateX(-${slideIdx * 100}%)`;
  }
  window.nextSlide = function() {
    slideIdx = (slideIdx + 1) % slideCount;
    updateSlide();
  };
  window.prevSlide = function() {
    slideIdx = (slideIdx - 1 + slideCount) % slideCount;
    updateSlide();
  };
  setInterval(window.nextSlide, 5000);

  // Read more toggle
  readMoreBtn.addEventListener('click', () => {
    marketExtra.classList.toggle('open');
    readMoreIcon.textContent = marketExtra.classList.contains('open') ? '▲' : '▼';
  });

  // Dropdown toggles
  btnFilters.addEventListener('click', (e) => {
    e.stopPropagation();
    filtersPanel.classList.toggle('open');
    columnsPanel.classList.remove('open');
  });
  btnColumns.addEventListener('click', (e) => {
    e.stopPropagation();
    columnsPanel.classList.toggle('open');
    filtersPanel.classList.remove('open');
  });
  document.addEventListener('click', () => {
    filtersPanel.classList.remove('open');
    columnsPanel.classList.remove('open');
  });
  filtersPanel.addEventListener('click', e => e.stopPropagation());
  columnsPanel.addEventListener('click', e => e.stopPropagation());

  // Column toggles
  columnsPanel.querySelectorAll('input[type="checkbox"]').forEach(cb => {
    cb.addEventListener('change', () => {
      const col = cb.dataset.col;
      if (cb.checked) visibleCols.add(col); else visibleCols.delete(col);
      renderTable();
    });
  });

  // Sort controls
  sortMcap.addEventListener('click', () => {
    currentSort = 'mcap';
    sortDir = 'desc';
    sortMcap.classList.add('active');
    sortVol.classList.remove('active');
    renderTable();
  });
  sortVol.addEventListener('click', () => {
    currentSort = 'vol';
    sortDir = 'desc';
    sortVol.classList.add('active');
    sortMcap.classList.remove('active');
    renderTable();
  });

  // Header sort
  document.querySelectorAll('.crypto-table thead th.sortable').forEach(th => {
    th.addEventListener('click', () => {
      const sortKey = th.dataset.sort;
      if (currentSort === sortKey) {
        sortDir = sortDir === 'asc' ? 'desc' : 'asc';
      } else {
        currentSort = sortKey;
        sortDir = 'desc';
      }
      document.querySelectorAll('.crypto-table thead th').forEach(t => t.classList.remove('sort-asc','sort-desc'));
      th.classList.add(sortDir === 'asc' ? 'sort-asc' : 'sort-desc');
      renderTable();
    });
  });

  // Category tabs
  document.querySelectorAll('[data-category]').forEach(tab => {
    tab.addEventListener('click', () => {
      document.querySelectorAll('[data-category]').forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      currentCategory = tab.dataset.category;
      currentPage = 1;
      renderTable();
    });
  });

  // Network tabs
  document.querySelectorAll('[data-network]').forEach(tab => {
    tab.addEventListener('click', () => {
      document.querySelectorAll('[data-network]').forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      currentNetwork = tab.dataset.network;
      currentPage = 1;
      renderTable();
    });
  });

  // Pagination
  pagination.querySelectorAll('.page-btn[data-page]').forEach(btn => {
    btn.addEventListener('click', () => {
      pagination.querySelectorAll('.page-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentPage = parseInt(btn.dataset.page);
      renderTable();
      window.scrollTo({ top: document.getElementById('cryptoTable').offsetTop - 120, behavior: 'smooth' });
    });
  });

  renderTable();
})();
"""

with open('/app/output/index.html', 'a') as f:
    f.write(js)
    f.write("\n</script>\n</body>\n</html>\n")

print("Done")
